export const getTourPrimaryDialogueText = (currentStep) => {
    switch (currentStep) {
        case 1:
            return 'Take control of your digital identity';
        case 2:
            return 'Take control of your digital identity';
        case 3:
            return 'Privately prove your identity across the web';
        case TOUR_TOTAL_STEPS:
            return 'Get started';
        default:
            return '';
    }
};
export const getTourSecondaryDialogueText = (currentStep) => {
    switch (currentStep) {
        case 1:
            return 'Self is the easiest way to verify your identity safely wherever you are.';
        case 2:
            return 'Self is the easiest way to verify your identity safely wherever you are.';
        case 3:
            return 'Gain special access online or even earn rewards just for being human';
        case TOUR_TOTAL_STEPS:
            return 'Register with Self using your passport or biometric ID to prove your identity across the web without revealing your personal information.';
        default:
            return '';
    }
};
export const getTourSecondaryButtonText = (currentStep) => {
    switch (currentStep) {
        case TOUR_TOTAL_STEPS:
            return 'Recover your account';
        default:
            return undefined;
    }
};
export const getTourPrimaryButtonText = (currentStep) => {
    switch (currentStep) {
        case 1:
        case 2:
        case 3:
            return 'Next';
        case TOUR_TOTAL_STEPS:
            return 'Get started';
    }
    return '';
};
