import { spacing } from '@selfxyz/euclid-core';
export const insetLayoutSpacing = {
    edgeTop: spacing.smPlus,
    content: spacing.mdLg,
    footer: spacing.lgXl,
};
export function getInsetAwarePadding({ inset = 0, min = 0, extra = 0, }) {
    return inset + min + extra;
}
export function getTopSafePadding(insets, minPadding = 0, extra = 0) {
    return getInsetAwarePadding({
        inset: insets.top,
        min: minPadding,
        extra,
    });
}
export function getBottomSafePadding(insets, minPadding = 0, extra = 0) {
    return getInsetAwarePadding({
        inset: insets.bottom,
        min: minPadding,
        extra,
    });
}
export function getBottomInsetOrPadding(insets, minPadding) {
    return Math.max(insets.bottom, minPadding);
}
export function getInsetAwareScreenStyle(insets, { topMinPadding = 0, bottomMinPadding, } = {}) {
    return {
        paddingTop: getTopSafePadding(insets, topMinPadding),
        ...(bottomMinPadding !== undefined
            ? { paddingBottom: getBottomSafePadding(insets, bottomMinPadding) }
            : {}),
    };
}
export function getInsetAwareHeaderStyle(insets, { minTopPadding = 0, } = {}) {
    return {
        paddingTop: getTopSafePadding(insets, minTopPadding),
    };
}
export function getInsetAwareScrollContentStyle(insets, { paddingX = insetLayoutSpacing.content, paddingTop = insetLayoutSpacing.content, minBottomPadding = insetLayoutSpacing.footer, } = {}) {
    return {
        paddingLeft: paddingX,
        paddingRight: paddingX,
        paddingTop,
        paddingBottom: getBottomSafePadding(insets, minBottomPadding),
    };
}
export function getInsetAwareFooterStyle(insets, { paddingX = insetLayoutSpacing.content, paddingTop = insetLayoutSpacing.content, minBottomPadding = insetLayoutSpacing.footer, } = {}) {
    return {
        paddingLeft: paddingX,
        paddingRight: paddingX,
        paddingTop,
        paddingBottom: getBottomSafePadding(insets, minBottomPadding),
    };
}
// Allow nested flex children to shrink so inner overflow containers can scroll.
export const flexColumnFill = {
    display: 'flex',
    flexDirection: 'column',
    flex: 1,
    minHeight: 0,
};
export const scrollYFill = {
    flex: 1,
    minHeight: 0,
    overflowY: 'auto',
};
