var detectDefaultPlatform = () => {
  if (typeof navigator === "undefined" || !navigator.userAgent) {
    return "unknown";
  }
  const userAgent = navigator.userAgent.toLowerCase();
  if (/iphone|ipad|ipod/.test(userAgent)) {
    return "ios";
  }
  if (/android/.test(userAgent)) {
    return "android";
  }
  return "web";
};
