function mergeConfig(base, override) {
  return {
    ...base,
    ...override,
    timeouts: { ...base.timeouts, ...override.timeouts ?? {} },
    features: { ...base.features, ...override.features ?? {} },
    devConfig: override.devConfig ?? base.devConfig
  };
}

