// src/proving/internal/statusHandlers.ts
function handleStatusCode(data, circuitType) {
  const result = {
    shouldDisconnect: false,
    analytics: []
  };
  if (data.status === 3 || data.status === 5) {
    result.shouldDisconnect = true;
    result.stateUpdate = {
      error_code: data.error_code,
      reason: data.reason,
      socketConnection: null
    };
    result.actorEvent = { type: "PROVE_FAILURE" };
    result.analytics = [
      {
        event: "SOCKETIO_PROOF_FAILURE",
        data: {
          error_code: data.error_code,
          reason: data.reason
        }
      }
    ];
    return result;
  }
  if (data.status === 4) {
    result.shouldDisconnect = true;
    result.stateUpdate = {
      socketConnection: null
    };
    result.actorEvent = { type: "PROVE_SUCCESS" };
    result.analytics = [
      {
        event: "SOCKETIO_PROOF_SUCCESS"
      }
    ];
    if (circuitType === "register") {
      result.analytics.push({
        event: "REGISTER_COMPLETED"
      });
    }
    return result;
  }
  return result;
}
function parseStatusMessage(message) {
  if (typeof message === "string") {
    try {
      return JSON.parse(message);
    } catch {
      throw new Error("Invalid JSON message received");
    }
  }
  if (typeof message === "object" && message !== null) {
    return message;
  }
  throw new Error("Invalid message format");
}

