export const defaultSafeAreaInsets = {
    top: 0,
    bottom: 0,
};
export function resolveSafeAreaInsets(insets) {
    return {
        top: insets?.top ?? defaultSafeAreaInsets.top,
        bottom: insets?.bottom ?? defaultSafeAreaInsets.bottom,
    };
}
export function createSafeAreaProps(insets) {
    return {
        insets: resolveSafeAreaInsets(insets),
    };
}
