// src/utils/proving.ts
init_elliptic();
var elliptic2 = initElliptic();
var { ec: EC } = elliptic2;
var ec = new EC("p256");
var clientKey = ec.genKeyPair();
var clientPublicKeyHex = clientKey.getPublic(true, "hex");
function encryptAES256GCM(plaintext, key) {
  const iv = forge7.random.getBytesSync(12);
  const cipher = forge7.cipher.createCipher("AES-GCM", key);
  cipher.start({ iv, tagLength: 128 });
  cipher.update(forge7.util.createBuffer(plaintext, "utf8"));
  cipher.finish();
  const encrypted = cipher.output.getBytes();
  const authTag = cipher.mode.tag.getBytes();
  return {
    nonce: Array.from(Buffer2.from(iv, "binary")),
    cipher_text: Array.from(Buffer2.from(encrypted, "binary")),
    auth_tag: Array.from(Buffer2.from(authTag, "binary"))
  };
}
function bigIntReplacer(_key, value) {
  return typeof value === "bigint" ? value.toString() : value;
}
function getPayload(inputs, circuitType, circuitName, endpointType, endpoint, version = 1, userDefinedData = "", selfDefinedData = "") {
  if (circuitType === "disclose") {
    const type = circuitName === "vc_and_disclose" ? "disclose" : circuitName === "vc_and_disclose_aadhaar" ? "disclose_aadhaar" : circuitName === "vc_and_disclose_kyc" ? "disclose_kyc" : "disclose_id";
    const payload = {
      type,
      endpointType,
      endpoint,
      onchain: endpointType === "celo" ? true : false,
      circuit: {
        name: circuitName,
        inputs: JSON.stringify(inputs, bigIntReplacer)
      },
      version,
      userDefinedData,
      selfDefinedData
    };
    return payload;
  } else {
    const type = circuitName === "register_aadhaar" ? "register_aadhaar" : circuitName === "register_kyc" ? "register_kyc" : circuitType;
    const payload = {
      type,
      onchain: true,
      endpointType,
      circuit: {
        name: circuitName,
        inputs: JSON.stringify(inputs, bigIntReplacer)
      }
    };
    return payload;
  }
}
function getWSDbRelayerUrl(endpointType) {
  return endpointType === "celo" || endpointType === "https" ? WS_DB_RELAYER : WS_DB_RELAYER_STAGING;
}

