/**
 * Enables anti-aliased font rendering in web/react-native-web environments.
 * Safe to call in native runtimes where `document` is unavailable.
 */
export function enableWebFontSmoothing() {
    const rootStyle = globalThis.document?.documentElement
        ?.style;
    if (!rootStyle?.setProperty) {
        return;
    }
    rootStyle.setProperty('-webkit-font-smoothing', 'antialiased');
    rootStyle.setProperty('-moz-osx-font-smoothing', 'grayscale');
}
