export const validateButtonProps = (variant, text, hasIcon) => {
    if ((variant === 'primary-icon-label' || variant === 'secondary-icon-label') &&
        (!text || !hasIcon)) {
        console.warn(`Button: variant "${variant}" requires both text and icon props`);
    }
    if ((variant === 'primary-icon' || variant === 'secondary-icon') &&
        !hasIcon) {
        console.warn(`Button: variant "${variant}" requires icon prop`);
    }
    if ((variant === 'primary-no-icon' || variant === 'secondary-label') &&
        !text) {
        console.warn(`Button: variant "${variant}" requires text prop`);
    }
    if ((variant === 'mega-primary' || variant === 'mega-secondary') && !text) {
        console.warn(`Button: variant "${variant}" requires text prop`);
    }
    if ((variant === 'picker' || variant === 'alt-id') && !text) {
        console.warn(`Button: variant "${variant}" requires text prop`);
    }
    if ((variant === 'primary-stacked' || variant === 'secondary-stacked') &&
        (!text || !hasIcon)) {
        console.warn(`Button: variant "${variant}" requires both text and icon props`);
    }
    if ((variant === 'id-picker-flag' || variant === 'id-selected') && !text) {
        console.warn(`Button: variant "${variant}" requires text prop`);
    }
};
